func readInt(r *bufio.Reader) (int, error) {
	var x int
	var c byte
	var err error
	for {
		c, err = r.ReadByte()
		if err != nil {
			return x, err
		}
		if c >= '0' && c <= '9' {
			break
		}
	}
	for c >= '0' && c <= '9' {
		x = x*10 + int(c-'0')
		c, err = r.ReadByte()
		if err != nil {
